static ymcc::input::frameSubmission::Sample inputHostFrameSubmissionSample(const InputCaptureGamepadSnapshot* sample) {
    if(!sample)return {};
    const bool msi=sample->inputSource=="msi-dinput";
    const bool xinput=(sample->inputSource=="xinput" || sample->inputSource=="xinput-any-connected") && sample->connectedMask!=0;
    return {{sample->readAttemptSequence,sample->readStartedTick,sample->readCompletedTick,
        sample->readPowerGeneration,sample->readTopologyGeneration,sample->readContextStable},
        sample->readIdentityGeneration,sample->readMsiSourceRevision,sample->live,xinput||msi,msi,sample->readMsiModeGeneration};
}
